<?php
require __DIR__.'/bootstrap.php';if(PHP_SAPI!=='cli')fail('CLI only.',403);
try{$token=config()['github_token']??'';if(!$token)throw new RuntimeException('Set github_token in private/config.php.');$c=curl_init('https://api.github.com/repos/khaled9599/the-vie-tcz-performance/contents/data/metrics.json?ref=main');curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>60,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$token,'Accept: application/vnd.github+json','User-Agent: TCZ-Hostinger-Sync','X-GitHub-Api-Version: 2022-11-28']]);$raw=curl_exec($c);$code=curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);if($code!==200||!is_string($raw))throw new RuntimeException('GitHub download failed ('.$code.'). Previous report kept.');$body=json_decode($raw,true,512,JSON_THROW_ON_ERROR);if(($body['encoding']??'')!=='base64')throw new RuntimeException('Unexpected GitHub response.');$json=base64_decode($body['content']??'',true);if($json===false)throw new RuntimeException('Invalid download.');$s=json_decode($json,true,512,JSON_THROW_ON_ERROR);validate_snapshot($s);$old=snapshot();if(strtotime($s['refreshedAt'])<strtotime($old['refreshedAt']))throw new RuntimeException('Older report rejected.');$temp=tempnam(__DIR__,'metrics-');if(file_put_contents($temp,$json)===false)throw new RuntimeException('Write failed.');chmod($temp,0600);if(!rename($temp,__DIR__.'/metrics.json')){unlink($temp);throw new RuntimeException('Report replacement failed.');}echo 'Verified report synced: '.$s['refreshedAt'].PHP_EOL;}catch(Throwable $e){fwrite(STDERR,$e instanceof RuntimeException?$e->getMessage().PHP_EOL:"Sync failed. Previous report kept.\n");exit(1);}
